import { AuthKind } from '../../../config/constants';
import { IAuthContext } from '../interfaces/auth.interface';
import { getUserById } from '../dm/user.dm';
import { StaffDM } from '../../staff';

// ============================================================
// Actor — a readable name for "who did this" (bill generated by, paid by, ...)
// ============================================================

export const getActorName = async (auth?: IAuthContext): Promise<string> => {
  if (!auth) return 'Unknown';

  if (auth.kind === AuthKind.STAFF && auth.staffId) {
    const staff = await StaffDM.getStaffById(auth.staffId);
    return staff ? `${staff.name} (waiter)` : 'Staff';
  }

  if (auth.userId) {
    const user = await getUserById(auth.userId);
    return user?.name || user?.email || 'Owner';
  }

  return 'Unknown';
};
